import * as React from 'react';
import * as NumberTickerPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface NumberTickerProps extends React.ComponentPropsWithoutRef<typeof NumberTickerPrimitive.NumberTicker> {
  className?: string;
}

export const NumberTicker = React.forwardRef<HTMLDivElement, NumberTickerProps>(
  ({ className, children, ...props }, ref) => (
    <NumberTickerPrimitive.NumberTicker
      ref={ref}
      className={clsx(
        'inline-block tabular-nums font-bold tracking-tight text-foreground',
        className
      )}
      {...props}
    >
      {children}
    </NumberTickerPrimitive.NumberTicker>
  )
);
NumberTicker.displayName = 'NumberTicker';

