import { NumberTicker } from '@exhuma/core';

class ExhumaNumberTickerElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-number-ticker');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-number-ticker')) {
  customElements.define('exhuma-number-ticker', ExhumaNumberTickerElement);
}

