import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as NumberTickerPrimitive from '@exhuma/core';

export interface NumberTickerProps extends ViewProps {
  children?: React.ReactNode;
}

export function NumberTicker({ style, children, ...props }: NumberTickerProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

